package com.flowforge.performance

import com.flowforge.core.contracts.{SchemaConforms, SchemaPolicy}
import com.flowforge.core.contracts.derive.Shape
import org.openjdk.jmh.annotations._
import org.openjdk.jmh.infra.Blackhole
import java.util.concurrent.TimeUnit
import scala.util.Random

/**
 * Comprehensive JMH benchmarks for FlowForge schema validation performance.
 * 
 * These benchmarks measure the runtime performance of code generated by SchemaConformsMacros
 * across different schema complexity levels and validation policies.
 */
@BenchmarkMode(Array(Mode.Throughput, Mode.AverageTime))
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 5, time = 1, timeUnit = TimeUnit.SECONDS)
@Measurement(iterations = 10, time = 1, timeUnit = TimeUnit.SECONDS)
@Fork(value = 2, jvmArgs = Array("-Xmx2g", "-XX:+UseG1GC"))
@State(Scope.Benchmark)
class SchemaValidationBenchmarks {

  // Simple schema test data
  case class SimpleUser(id: Int, name: String, active: Boolean)
  case class SimpleUserContract(id: Int, name: String, active: Boolean)

  // Nested schema test data
  case class Address(street: String, city: String, zipCode: String)
  case class Contact(email: String, phone: Option[String])
  case class NestedUser(
    id: Long,
    profile: UserProfile,
    addresses: List[Address],
    contacts: Map[String, Contact],
    metadata: Option[Map[String, String]]
  )
  case class UserProfile(firstName: String, lastName: String, age: Int, verified: Boolean)
  
  case class NestedUserContract(
    id: Long,
    profile: UserProfile,
    addresses: List[Address],
    contacts: Map[String, Contact],
    metadata: Option[Map[String, String]]
  )

  // Large schema test data (50+ fields)
  case class LargeSchema(
    field1: String, field2: Int, field3: Long, field4: Double, field5: Boolean,
