    field26: String, field27: Int, field28: Long, field29: Double, field30: Boolean,
    field31: String, field32: Int, field33: Long, field34: Double, field35: Boolean,
    field36: String, field37: Int, field38: Long, field39: Double, field40: Boolean,
    field41: String, field42: Int, field43: Long, field44: Double, field45: Boolean,
    field46: String, field47: Int, field48: Long, field49: Double, field50: Boolean,
    field51: Option[String], field52: Option[Int], field53: Option[Long],
    field54: List[String], field55: List[Int], field56: Map[String, Int]
