  case class Level10(value: String, data: Map[String, List[Option[String]]])

  case class Level1Contract(value: String, level2: Level2)

  // Complex collection schema
  case class ComplexCollections(
    nestedLists: List[List[List[String]]],
    nestedMaps: Map[String, Map[String, Map[String, Int]]],
    mixedCollections: List[Map[String, Option[List[Int]]]],
    optionalCollections: Option[List[Map[String, Option[String]]]],
    complexTuples: List[(String, Int, Option[Boolean], Map[String, Double])]
