  var simpleUser: SimpleUser = _
  var nestedUser: NestedUser = _
  var largeSchema: LargeSchema = _
  var extremeSchema: ExtremeSchema = _
  var deeplyNested: Level1 = _
  var complexCollections: ComplexCollections = _
  var policyTest: PolicyTestOut = _

  @Setup(Level.Trial)
  def setup(): Unit = {
    val random = new Random(42) // Fixed seed for reproducible results

    simpleUser = SimpleUser(
      id = random.nextInt(10000),
      name = s"User${random.nextInt(1000)}",
      active = random.nextBoolean()
    )

    nestedUser = NestedUser(
      id = random.nextLong(),
      profile = UserProfile("John", "Doe", 30, true),
      addresses = List(
        Address("123 Main St", "Anytown", "12345"),
        Address("456 Oak Ave", "Somewhere", "67890")
      ),
      contacts = Map(
        "primary" -> Contact("john@example.com", Some("555-1234")),
        "secondary" -> Contact("john.doe@work.com", None)
      ),
      metadata = Some(Map("source" -> "api", "version" -> "1.0"))
    )

    largeSchema = LargeSchema(
      "s1", 1, 1L, 1.0, true, "s2", 2, 2L, 2.0, false,
      "s3", 3, 3L, 3.0, true, "s4", 4, 4L, 4.0, false,
      "s5", 5, 5L, 5.0, true, "s6", 6, 6L, 6.0, false,
      "s7", 7, 7L, 7.0, true, "s8", 8, 8L, 8.0, false,
      "s9", 9, 9L, 9.0, true, "s10", 10, 10L, 10.0, false,
      "s11", 11, 11L, 11.0, true, "s12", 12, 12L, 12.0, false,
      "s13", 13, 13L, 13.0, true, "s14", 14, 14L, 14.0, false,
      "s15", 15, 15L, 15.0, true, "s16", 16, 16L, 16.0, false,
      Some("opt1"), Some(52), Some(53L),
      List("item1", "item2"), List(1, 2, 3), Map("key1" -> 1, "key2" -> 2)
    )

    extremeSchema = ExtremeSchema(
      "s1", 1, 1L, 1.0, true, "s2", 2, 2L, 2.0, false,
      "s3", 3, 3L, 3.0, true, "s4", 4, 4L, 4.0, false,
      "s5", 5, 5L, 5.0, true, "s6", 6, 6L, 6.0, false,
      "s7", 7, 7L, 7.0, true, "s8", 8, 8L, 8.0, false,
      "s9", 9, 9L, 9.0, true, "s10", 10, 10L, 10.0, false,
      "s11", 11, 11L, 11.0, true, "s12", 12, 12L, 12.0, false,
      "s13", 13, 13L, 13.0, true, "s14", 14, 14L, 14.0, false,
      "s15", 15, 15L, 15.0, true, "s16", 16, 16L, 16.0, false,
      "s17", 17, 17L, 17.0, true, "s18", 18, 18L, 18.0, false,
      "s19", 19, 19L, 19.0, true, "s20", 20, 20L, 20.0, false,
      "s21", 21, 21L, 21.0, true, "s22", 22, 22L, 22.0, false,
      "s23", 23, 23L, 23.0, true, "s24", 24, 24L, 24.0, false,
      "s25", 25, 25L, 25.0, true, "s26", 26, 26L, 26.0, false,
      "s27", 27, 27L, 27.0, true, "s28", 28, 28L, 28.0, false,
      "s29", 29, 29L, 29.0, true, "s30", 30, 30L, 30.0, false,
      Some("opt1"), Some(102), Some(103L), Some(104.0), Some(true),
      List("a", "b"), List(1, 2), List(1L, 2L), List(1.0, 2.0), List(true, false),
      Map("k1" -> "v1"), Map("k1" -> 1), Map("k1" -> 1L), Map("k1" -> 1.0), Map("k1" -> true)
    )

    deeplyNested = Level1(
      "level1",
      Level2(
        2,
        Level3(
          true,
          Level4(
            4.0,
            Level5(
              5L,
              Level6(
                "level6",
                Level7(
                  7,
                  Level8(
                    false,
                    Level9(
                      9.0,
                      Level10("level10", Map("key" -> List(Some("deep"), None, Some("nested"))))
                    )
                  )
                )
              )
            )
          )
        )
      )
    )

    complexCollections = ComplexCollections(
      nestedLists = List(
        List(List("a", "b"), List("c", "d")),
        List(List("e", "f"), List("g", "h"))
      ),
      nestedMaps = Map(
        "level1" -> Map(
          "level2" -> Map("level3" -> 42)
        )
      ),
      mixedCollections = List(
        Map("key1" -> Some(List(1, 2, 3)), "key2" -> None),
        Map("key3" -> Some(List(4, 5, 6)))
      ),
      optionalCollections = Some(List(
        Map("opt1" -> Some("value1"), "opt2" -> None)
      )),
      complexTuples = List(
        ("tuple1", 1, Some(true), Map("metric" -> 1.5)),
        ("tuple2", 2, None, Map("metric" -> 2.5))
      )
    )

    policyTest = PolicyTestOut(1, "test", "test@example.com", Some(25))
  }

  // ============================================================================
  // Simple Schema Benchmarks
  // ============================================================================

  @Benchmark
  def simpleSchemaExactValidation(bh: Blackhole): Unit = {
    val conforms = implicitly[SchemaConforms[SimpleUser, SimpleUserContract, SchemaPolicy.Exact]]
    bh.consume(conforms)
    bh.consume(simpleUser)
  }

