  // ============================================================================
  // Policy Comparison Benchmarks
  // ============================================================================

  @Benchmark
  def policyComparisonExact(bh: Blackhole): Unit = {
    // This will fail at compile time, but we measure the compilation overhead
    try {
      val conforms = implicitly[SchemaConforms[PolicyTestOut, PolicyTestContract, SchemaPolicy.Exact]]
      bh.consume(conforms)
    } catch {
      case _: Throwable => // Expected compilation failure
    }
    bh.consume(policyTest)
  }

