/**
 * Specialized benchmarks for measuring compilation overhead and macro expansion performance.
 * These benchmarks focus on the compile-time aspects of schema validation.
 */
@BenchmarkMode(Array(Mode.SingleShotTime))
@OutputTimeUnit(TimeUnit.MILLISECONDS)
@Warmup(iterations = 0)
@Measurement(iterations = 5)
@Fork(value = 1, jvmArgs = Array("-Xmx4g", "-XX:+UseG1GC", "-XX:+PrintGC"))
@State(Scope.Benchmark)
class CompilationOverheadBenchmarks {

  // These benchmarks measure the overhead of implicit resolution and macro expansion
  // by timing the creation of SchemaConforms instances

  @Benchmark
  def compileTimeSimpleSchema(bh: Blackhole): Unit = {
    case class TestOut(id: Int, name: String)
    case class TestContract(id: Int, name: String)
    val conforms = implicitly[SchemaConforms[TestOut, TestContract, SchemaPolicy.Exact]]
    bh.consume(conforms)
  }

  @Benchmark
  def compileTimeMediumSchema(bh: Blackhole): Unit = {
    case class TestOut(
      id: Int, name: String, email: String, age: Int, active: Boolean,
      address: String, phone: String, country: String, city: String, zipCode: String
    )
    case class TestContract(
      id: Int, name: String, email: String, age: Int, active: Boolean,
      address: String, phone: String, country: String, city: String, zipCode: String
    )
    val conforms = implicitly[SchemaConforms[TestOut, TestContract, SchemaPolicy.Exact]]
    bh.consume(conforms)
  }

  @Benchmark
  def compileTimeNestedSchema(bh: Blackhole): Unit = {
    case class Address(street: String, city: String)
    case class Contact(email: String, phone: Option[String])
    case class TestOut(id: Int, name: String, address: Address, contacts: List[Contact])
    case class TestContract(id: Int, name: String, address: Address, contacts: List[Contact])
    val conforms = implicitly[SchemaConforms[TestOut, TestContract, SchemaPolicy.Exact]]
    bh.consume(conforms)
  }

  @Benchmark
  def compileTimeComplexCollections(bh: Blackhole): Unit = {
    case class TestOut(
      lists: List[List[String]],
      maps: Map[String, Map[String, Int]],
      options: Option[List[Map[String, Option[String]]]]
    )
    case class TestContract(
      lists: List[List[String]],
      maps: Map[String, Map[String, Int]],
      options: Option[List[Map[String, Option[String]]]]
    )
    val conforms = implicitly[SchemaConforms[TestOut, TestContract, SchemaPolicy.Exact]]
    bh.consume(conforms)
  }
}